begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1000000-0000-0000-0000-000000000001','automation-owner@test.invalid'),('e1000000-0000-0000-0000-000000000002','automation-other@test.invalid');
insert into public.tenants(id,name,slug)values('e2000000-0000-0000-0000-000000000001','Automation A','automation-a'),('e2000000-0000-0000-0000-000000000002','Automation B','automation-b');
insert into public.properties(id,tenant_id,name,property_type)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Hotel A','hotel'),('e3000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','owner'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','owner');
insert into public.guests(id,tenant_id,full_name,phone)values('e4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Asha','+919111111111');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e6000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','12345678001','12345678002','+919999999999','automation-test');
\set pid e3000000-0000-0000-0000-000000000001
\set tenant e2000000-0000-0000-0000-000000000001
\set guest e4000000-0000-0000-0000-000000000001
\set rid e5000000-0000-0000-0000-000000000001
\set owner e1000000-0000-0000-0000-000000000001
set local role service_role;
select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[{"provider_id":"901","name":"journey_welcome","language":"en_US","category":"utility","provider_status":"APPROVED","body":"Hello {{guest_name}}, welcome to {{hotel_name}}. Upload securely: {{portal_url}}. Reply Hi to choose updates.","parameter_names":["guest_name","hotel_name","portal_url"],"supported":true,"service_supported":true,"definition":{"components":[{"type":"BODY"},{"type":"HEADER","format":"IMAGE"},{"type":"BUTTONS","buttons":[{"type":"URL","url":"https://hotel.test/location","text":"Location"}]}]}}]');
reset role;
insert into public.whatsapp_template_assets values(:'pid','901','https://hotel.test/front.jpg');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',:'owner','role','authenticated')::text,true);
select id as tid from public.message_templates where property_id=:'pid'and name='journey_welcome' \gset

select is(public.whatsapp_template_deletion_context(:'pid',:'tid')->>'can_delete','true','unused synced template can be deleted');
select throws_ok(format('select public.whatsapp_template_deletion_context(%L,%L)','e3000000-0000-0000-0000-000000000002',:'tid'),'42501',null,'cross-hotel deletion context forbidden');
select throws_ok(format('select public.begin_whatsapp_template_deletion(%L,%L,%L,%L,%L)',:'pid',:'tid','901','wrong_name','en_US'),'40001',null,'exact name confirmation required');
select throws_ok(format('select public.begin_whatsapp_template_deletion(%L,%L,%L,%L,%L)',:'pid',:'tid','901','journey_welcome','hi'),'40001',null,'language cannot be swapped');
select public.save_whatsapp_automation_rule(:'pid','checked_in',0,true,:'tid','["guest_name","hotel_name","portal_url"]',0);
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')->>'can_delete','false','active event blocks deletion');
select public.save_whatsapp_automation_rule(:'pid','checked_in',1,false,:'tid','["guest_name","hotel_name","portal_url"]',0);
reset role;
insert into public.whatsapp_guest_menu(property_id,enabled,data)values(:'pid',true,jsonb_build_object('categories',jsonb_build_array(jsonb_build_object('enabled',true,'services',jsonb_build_array(jsonb_build_object('enabled',true,'template_id',:'tid'))))));
set local role authenticated;
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')#>>'{usage,services}','1','published menu usage is checked');
select throws_ok(format('select public.begin_whatsapp_template_deletion(%L,%L,%L,%L,%L)',:'pid',:'tid','901','journey_welcome','en_US'),'22023',null,'published menu blocks deletion');
reset role;
update public.whatsapp_guest_menu set enabled=false where property_id=:'pid';
insert into public.whatsapp_campaigns(tenant_id,property_id,name,body,filters,template_id,selection_mode,status)values(:'tenant',:'pid','Deletion guard QA','Test campaign','{}',:'tid','all','scheduled');
set local role authenticated;
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')#>>'{usage,campaigns}','1','scheduled campaign blocks deletion');
reset role;
update public.whatsapp_campaigns set status='cancelled'where property_id=:'pid';
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id)values('e7000000-0000-0000-0000-000000000001',:'tenant',:'pid','e6000000-0000-0000-0000-000000000001','919111111111');
insert into public.messages(tenant_id,property_id,conversation_id,direction,type,body,template_id,status)values(:'tenant',:'pid','e7000000-0000-0000-0000-000000000001','out','template','Historical test',:'tid','queued');
set local role authenticated;
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')#>>'{usage,messages}','1','queued message blocks deletion');
reset role;
update public.messages set status='sent'where property_id=:'pid';
insert into public.whatsapp_connections(tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e2000000-0000-0000-0000-000000000002','e3000000-0000-0000-0000-000000000002','12345678999','12345678002','+919888888888','shared-test');
set local role authenticated;
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')->>'can_delete','false','another hotel sharing the WABA blocks deletion');
reset role;
update public.whatsapp_connections set status='disabled'where property_id='e3000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('t.job',public.begin_whatsapp_template_deletion(:'pid',:'tid','901','journey_welcome','en_US')::text,true);
select throws_ok(format('select public.begin_whatsapp_template_deletion(%L,%L,%L,%L,%L)',:'pid',:'tid','901','journey_welcome','en_US'),'22023',null,'double click cannot reserve a second provider request');
select throws_ok(format('select public.save_whatsapp_automation_rule(%L,%L,2,true,%L,%L,0)',:'pid','checked_in',:'tid','["guest_name","hotel_name","portal_url"]'),'22023',null,'cannot activate rule during provider deletion');
reset role;
select throws_ok(format('update public.whatsapp_guest_menu set enabled=true where property_id=%L',:'pid'),'22023',null,'cannot publish menu during deletion');
select throws_ok(format('update public.whatsapp_campaigns set status=%L where property_id=%L','scheduled',:'pid'),'22023',null,'cannot schedule campaign during deletion');
select throws_ok(format('update public.messages set status=%L where property_id=%L','queued',:'pid'),'22023',null,'cannot requeue a template during deletion');
set local role service_role;
select ok(public.finish_whatsapp_template_deletion((current_setting('t.job')::jsonb->>'operation')::uuid,'deleted'),'successful provider deletion retires local template');
select ok(public.finish_whatsapp_template_deletion((current_setting('t.job')::jsonb->>'operation')::uuid,'deleted'),'provider completion is idempotent');
reset role;
select is((select count(*)::integer from public.messages where property_id=:'pid'),1,'historical messages are retained');
select is((select provider_status from public.message_templates where id=:'tid'),'DELETED','provider deletion tracked distinctly');
set local role authenticated;
select is((select count(*)::integer from jsonb_array_elements(public.whatsapp_automation_workspace(:'pid')->'templates')t where t->>'id'=:'tid'),0,'deleted template removed from library');
select is((select count(*)::integer from jsonb_array_elements(public.whatsapp_service_templates(:'pid'))t where t->>'id'=:'tid'),0,'deleted template removed from menu picker');
select is(public.begin_whatsapp_template_deletion(:'pid',:'tid','901','journey_welcome','en_US')->>'already_deleted','true','stale client cannot delete twice');
set local role service_role;
select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[]');
reset role;
select is((select provider_status from public.message_templates where id=:'tid'),'DELETED','directory refresh never resurrects deleted template');
set local role service_role;
select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[{"provider_id":"902","name":"journey_welcome","language":"en_US","category":"utility","provider_status":"APPROVED","body":"New version","parameter_names":[],"supported":true,"service_supported":true,"definition":{"components":[]}}]');
reset role;
select ok((select deleted_at is null and provider_template_id='902'from public.message_templates where id=:'tid'),'new provider ID under reused name can be used after Meta permits recreation');
set local role authenticated;
select set_config('t.job2',public.begin_whatsapp_template_deletion(:'pid',:'tid','902','journey_welcome','en_US')::text,true);
set local role service_role;
select public.finish_whatsapp_template_deletion((current_setting('t.job2')::jsonb->>'operation')::uuid,'uncertain');
reset role;
select ok((select deleted_at is null from public.message_templates where id=:'tid'),'timeout never falsely marks template deleted');
set local role authenticated;
select is(public.whatsapp_template_deletion_context(:'pid',:'tid')->>'can_delete','false','uncertain provider result blocks blind repeat');
set local role service_role;
select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[]');
reset role;
select ok((select deleted_at is not null from public.message_templates where id=:'tid'),'sync reconciles an interrupted deletion when provider confirms absence');
set local role anon;
select ok(not has_function_privilege('anon','public.begin_whatsapp_template_deletion(uuid,uuid,text,text,text)','execute'),'anonymous deletion forbidden');
select ok(not has_function_privilege('authenticated','public.finish_whatsapp_template_deletion(uuid,text)','execute'),'staff cannot forge provider deletion result');
select throws_ok($$select *from private.whatsapp_template_deletions$$,'42501',null,'operation audit is private');
select *from finish();rollback;
